INSERT INTO entity_citations (citation_id,entity_id,source_id,work_title,locus,quote,translator,translation_year,source_url,original_text_url,evidence_grade,evidence_note,needs_review,review_reason,verified_on,verify_method,display_order) VALUES
('CIT_ART_AGRAVAIN_MALORY','ENT_ART_AGRAVAIN','SRC_MALORY_MORTE','Malory, Le Morte d''Arthur','Malory, Le Morte d''Arthur','Ah Agravaine, Agravaine, said the king, Jesu forgive it thy soul, for thine evil will, that thou and thy brother Sir Mordred hadst unto Sir Launcelot, hath caused all this sorrow: and ever among these complaints the king wept and swooned. Then there came one unto Sir Gawaine, and told him how the queen was led away with Sir Launcelot, and nigh a twenty-four knights slain.','Sir Thomas Malory',1485,'None',NULL,'primary-verbatim',NULL,true,'Located by name; verify book/chapter.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ART_ELAINE_ASTOLAT_MALORY','ENT_ART_ELAINE_ASTOLAT','SRC_MALORY_MORTE','Malory, Le Morte d''Arthur','Malory, Le Morte d''Arthur','Of the great lamentation of the Fair Maid of Astolat when Launcelot should depart, and how she died for his love. .........................................................................................657 20 CHAPTER XX. How the corpse of the Maid of Astolat arrived to-fore King Arthur, and of the burying, and how Sir Launcelot offered the mass-penny. ...........................................................659 CHAPTER XXI.','Sir Thomas Malory',1485,'None',NULL,'primary-verbatim',NULL,true,'Located by name; verify book/chapter.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ART_EXCALIBUR_MALORY','ENT_ART_EXCALIBUR','SRC_MALORY_MORTE','Malory, Le Morte d''Arthur','Malory, Le Morte d''Arthur','How Arthur by the mean of Merlin gat Excalibur his sword of the Lady of the Lake. ..............................................................................................................................................65 2 CHAPTER XXVI. How tidings came to Arthur that King Rience had overcome eleven kings, and how he desired Arthur''s beard to trim his mantle. .........................................................................67 CHAPTER XXVII.','Sir Thomas Malory',1485,'None',NULL,'primary-verbatim',NULL,true,'Located by name; verify book/chapter.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ART_GAHERIS_MALORY','ENT_ART_GAHERIS','SRC_MALORY_MORTE','Malory, Le Morte d''Arthur','Malory, Le Morte d''Arthur','Thereat sat Sir Gawaine in great envy and told Gaheris his brother, yonder knight is put to great worship, the which grieveth me sore, for he slew our father King Lot, therefore I will slay him, said Gawaine, with a sword that was sent me that is passing trenchant.','Sir Thomas Malory',1485,'None',NULL,'primary-verbatim',NULL,true,'Located by name; verify book/chapter.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ART_GARETH_MALORY','ENT_ART_GARETH','SRC_MALORY_MORTE','Malory, Le Morte d''Arthur','Malory, Le Morte d''Arthur','Then, sir, he said, my name is Gareth, and brother unto Sir Gawaine of father and mother. Ah, sir, said Sir Launcelot, I am more gladder of you than I was; for ever me thought ye should be of great blood, and that ye came not to the court neither for meat nor for 189 drink. And then Sir Launcelot gave him the order of knighthood, and then Sir Gareth prayed him for to depart and let him go.','Sir Thomas Malory',1485,'None',NULL,'primary-verbatim',NULL,true,'Located by name; verify book/chapter.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ART_GREEN_KNIGHT_MALORY','ENT_ART_GREEN_KNIGHT','SRC_MALORY_MORTE','Malory, Le Morte d''Arthur','Malory, Le Morte d''Arthur','THEN was the cry of heralds and all manner of common people: The Green Knight hath done marvellously, and beaten all them of Orkney. And there the heralds numbered that Sir Tristram that sat upon the black horse had smitten down with spears and swords thirty knights; and Sir Palomides had smitten down twenty knights, and the most part of these fifty knights were of the house of King Arthur, and proved knights.','Sir Thomas Malory',1485,'None',NULL,'primary-verbatim',NULL,true,'Located by name; verify book/chapter.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ART_KING_LOT_MALORY','ENT_ART_KING_LOT','SRC_MALORY_MORTE','Malory, Le Morte d''Arthur','Malory, Le Morte d''Arthur','Then there swore King Lot, a passing good knight, and Sir Gawain''s father, that he would bring five thousand men of arms on horseback. Also there swore King Urience, that was Sir Uwain''s father, of the land of Gore, and he would bring six thousand men of arms on horseback. Also there swore King Idres of Cornwall, that he would bring five thousand men of arms on horseback. Also there swore King Cradelmas to bring five thousand men on horseback.','Sir Thomas Malory',1485,'None',NULL,'primary-verbatim',NULL,true,'Located by name; verify book/chapter.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ART_LAMORAK_MALORY','ENT_ART_LAMORAK','SRC_MALORY_MORTE','Malory, Le Morte d''Arthur','Malory, Le Morte d''Arthur','Well, said Sir Lamorak, since ye have said so largely unto me, my name is Sir Lamorak de Galis, son unto King Pellinore. Forsooth, I trow well, said Sir Tristram, for an ye said other I know the contrary. What are ye, said Sir Lamorak, that knoweth me? I am Sir Tristram de Liones. Ah, sir, remember ye not of the fall ye did give me once, and after ye refused me to fight on foot.','Sir Thomas Malory',1485,'None',NULL,'primary-verbatim',NULL,true,'Located by name; verify book/chapter.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ART_MORDRED_MALORY','ENT_ART_MORDRED','SRC_MALORY_MORTE','Malory, Le Morte d''Arthur','Malory, Le Morte d''Arthur','How by misadventure of an adder the battle began, where Mordred was slain, and Arthur hurt to the death ................................................................................................................728 CHAPTER V. How King Arthur commanded to cast his sword Excalibur into the water, and how he was delivered to ladies in a barge ...........................................................................................730 CHAPTER VI.','Sir Thomas Malory',1485,'None',NULL,'primary-verbatim',NULL,true,'Located by name; verify book/chapter.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ART_PELLINORE_MALORY','ENT_ART_PELLINORE','SRC_MALORY_MORTE','Malory, Le Morte d''Arthur','Malory, Le Morte d''Arthur','How King Pellinore took Arthur''s horse and followed the Questing Beast, and how Merlin met with Arthur. .........................................................................................................59 CHAPTER XXI. How Ulfius impeached Queen Igraine, Arthur''s mother, of treason; and how a knight came and desired to have the death of his master ..............................................................61 CHAPTER XXII.','Sir Thomas Malory',1485,'None',NULL,'primary-verbatim',NULL,true,'Located by name; verify book/chapter.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ART_ROUND_TABLE_MALORY','ENT_ART_ROUND_TABLE','SRC_MALORY_MORTE','Malory, Le Morte d''Arthur','Malory, Le Morte d''Arthur','How the Knights of the Round Table were ordained and their sieges blessed by the Bishop of Canterbury. WHEN King Arthur heard of the coming of Guenever and the hundred knights with the Table Round, then King Arthur made great joy for her coming, and that rich present, and said openly, This fair lady is passing welcome unto me, for I have loved her long, and therefore there is nothing so lief to me.','Sir Thomas Malory',1485,'None',NULL,'primary-verbatim',NULL,true,'Located by name; verify book/chapter.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ART_TRISTAN_MALORY','ENT_ART_TRISTAN','SRC_MALORY_MORTE','Malory, Le Morte d''Arthur','Malory, Le Morte d''Arthur','v.), the French romances of Tristan (Bks. viii.-x.) and of Launcelot (Bks. vi., xi.-xix.), and lastly to the English prose Morte Arthur of Harley MS. 2252 (Bks. xviii., xx., xxi.).','Sir Thomas Malory',1485,'None',NULL,'primary-verbatim',NULL,true,'Located by name; verify book/chapter.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1)
